import{j as t}from"./index-Durz8tzw.js";function o({segments:n}){const r=n.reduce((e,a)=>e+a.count,0);return r===0?null:t.jsxs("div",{className:"w-full",children:[t.jsx("div",{className:"flex h-8 rounded-lg overflow-hidden",children:n.map((e,a)=>{const i=e.count/r*100;return i===0?null:t.jsxs("div",{className:"flex items-center justify-center text-white text-xs font-bold transition-all duration-500 relative group",style:{width:`${i}%`,backgroundColor:e.color,borderRadius:a===0?"8px 0 0 8px":a===n.length-1?"0 8px 8px 0":"0"},children:[i>8&&t.jsx("span",{children:e.count}),t.jsxs("div",{className:"absolute bottom-full mb-2 left-1/2 -translate-x-1/2 bg-white text-slate-700 text-xs px-3 py-1.5 rounded-lg shadow-lg border border-slate-200 whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-10",children:[e.label,": ",e.count," (",i.toFixed(0),"%)"]})]},e.label)})}),t.jsx("div",{className:"flex mt-2",children:n.map(e=>{const a=e.count/r*100;return a===0?null:t.jsx("div",{className:"text-xs text-slate-500 text-center",style:{width:`${a}%`},children:e.label},e.label)})})]})}const s={NM001:{beruf:"Notary, Property Sales 2025",kiDescription:"AI Analysis: Dr. Katharina Bauer recently sold several properties in Frankfurt (net proceeds approx. 3.5M €). The proceeds are currently sitting uninvested across various call money accounts — a classic post-liquidity-event pattern. Prof. Hartmann (VV00004) recommended her as a notary from the Frankfurt physicians/lawyers network. Since no existing asset management mandate is in place and the wealth is unstructured, there is a high need for action. Recommendation: FairValue mandate with individual asset allocation, focusing on inflation-protected real assets and diversification. The probability of closing a mandate is estimated at 70% — the personal connection through Prof. Hartmann is a strong door-opener.",herkunft:"Referral Prof. Hartmann (VV00004) — Notary with 3.5M net proceeds from property sales",naechsterSchritt:"Initial meeting on 20.03.2026 — present FairValue mandate",quelleLabel:"Referral from Existing Client",herleitung:[{label:"Referrer",value:"Prof. Dr. Hartmann (VV00004), client since 2019"},{label:"Context",value:"Shared physicians/lawyers network Frankfurt"},{label:"Estimated Assets",value:"3,500,000 € (net proceeds from property sales 2025)"},{label:"Current Advisor",value:"No asset management mandate, funds spread across call money accounts"},{label:"Recommended Product",value:"FairValue mandate — individual asset management"},{label:"Next Step",value:"Initial meeting on 20.03.2026, FairValue mandate presentation"}]},NM002:{beruf:"Logistics Entrepreneur",kiDescription:"AI Analysis: The Schneider family is planning the sale of their logistics company with an estimated proceeds of approx. 3M €. The referral came directly from Tim Keller (VV00001, top client with 12.5M AuM), who knows the family from the IHK Rhein-Main board. Currently the assets are held at Commerzbank Wealth Management — a switch is realistic since the personal connection through Tim Keller builds trust. The WpHG questionnaire is the next formal step. Recommendation: FairValue mandate focusing on capital preservation and moderate growth following the company sale. Cross-selling potential: succession advisory and tax strategy.",herkunft:"Referral Tim Keller (VV00001) — logistics entrepreneur, estimated 3M €",naechsterSchritt:"WpHG questionnaire on 12.03. — then mandate proposal",quelleLabel:"Referral from Existing Client",herleitung:[{label:"Referrer",value:"Tim Keller (VV00001), top client 12.5M AuM"},{label:"Context",value:"Entrepreneur network Rhein-Main, joint IHK board membership"},{label:"Estimated Assets",value:"approx. 3,000,000 € (company sale planned)"},{label:"Current Advisor",value:"Commerzbank Wealth Management"},{label:"Next Step",value:"WpHG questionnaire on 12.03., then mandate proposal"}]},NM003:{beruf:"Lawyer, Partner at Commercial Law Firm",kiDescription:"AI Analysis: Charlotte Keller (32) is the daughter of top client Tim Keller (VV00001) and a partner at a commercial law firm in Frankfurt. Her estimated personal assets of approx. 800k € originate from savings and bonus payments — a typical profile of a young high earner without structured asset management. Her father actively gave the recommendation, raising the closing probability to 60%. NextGen strategy: SmartValue mandate as an entry point with a long-term perspective toward FairValue as assets grow. Long-term value: binding the 3rd generation to HRK LUNIS, with potential inheritance flow from the father's 12.5M mandate.",herkunft:"Daughter of Tim Keller (VV00001) — lawyer, 32 yrs, estimated personal assets 800k",naechsterSchritt:"Schedule initial meeting — present SmartValue mandate",quelleLabel:"NextGen (Client's Child)",herleitung:[{label:"Family Relation",value:"Daughter of Tim Keller (VV00001)"},{label:"Age / Profession",value:"32 years, lawyer / partner at commercial law firm Frankfurt"},{label:"Estimated Personal Assets",value:"approx. 800,000 € (savings + bonus payments)"},{label:"Door-Opener",value:"Father Tim Keller has given the referral"},{label:"Own Mandate?",value:"No — no personal asset management mandate in place"},{label:"Recommended Product",value:"SmartValue mandate (from 250k)"}]},NM004:{beruf:"Engineer in Family Business",kiDescription:"AI Analysis: Friedrich Keller (28) is the son of Tim Keller and works as an engineer in the family business (mechanical engineering). His current personal assets of approx. 250k € are still modest, but the strategic value is enormous: he is the likely successor of Keller Maschinenbau GmbH (estimated company value 4.5M €). A takeover in 3–5 years would bring significant assets. Recommendation: Establish the relationship now with a SmartValue mandate, with a long-term perspective toward FairValue after the company takeover. Approach indirectly through the father at the next quarterly meeting — low barrier due to the family trust base.",herkunft:"Son of Tim Keller (VV00001) — engineer, 28 yrs, potential business succession",naechsterSchritt:"Address through father at next quarterly meeting",quelleLabel:"NextGen (Client's Child)",herleitung:[{label:"Family Relation",value:"Son of Tim Keller (VV00001)"},{label:"Age / Profession",value:"28 years, engineer in family mechanical engineering business"},{label:"Estimated Personal Assets",value:"approx. 250,000 € (savings + shareholding unclear)"},{label:"Succession Context",value:"Potential takeover of family business in 3–5 years"},{label:"Next Step",value:"Address through father at quarterly meeting"}]},NM005:{beruf:"Resident Physician, Cardiology",kiDescription:'AI Analysis: Jan Hartmann (26) is the son of Prof. Dr. Hartmann (VV00004) and a resident physician in cardiology. Currently only 50k € in assets, but the income potential is exceptionally high: specialist qualification in 2–3 years (then 150k+ p.a.), followed by the foreseeable opening of his own practice with a long-term potential of 1M+ AuM. Classic "seed investment" in the NextGen strategy — early engagement of a future UHNW client. Recommendation: SmartValue Junior as a starting point, savings plan with monthly contributions. Approach through the father at his next regular appointment.',herkunft:"Son of Prof. Hartmann (VV00004) — resident physician, 26 yrs, high income potential",naechsterSchritt:"Address through Prof. Hartmann at next appointment",quelleLabel:"NextGen (Client's Child)",herleitung:[{label:"Family Relation",value:"Son of Prof. Dr. Hartmann (VV00004)"},{label:"Age / Profession",value:"26 years, resident physician in cardiology"},{label:"Income Potential",value:"High — specialist qualification in 2–3 years, then 150k+ p.a."},{label:"Long-Term Value",value:"Own practice foreseeable → long-term potential 1M+ AuM"},{label:"Next Step",value:"Address through father at next appointment"}]},NM006:{beruf:"University Freshman (18 yrs)",kiDescription:"AI Analysis: Noah Lindenberg (18) will begin his studies in 2026. His parents (Fam. Lindenberg, VV00002) plan to provide 100k € starting capital from their SaaS exit proceeds. Strategic value: early binding of the NextGen to HRK LUNIS before any personal wealth accumulation begins. At the parents' cash consolidation (5.5M €), the student portfolio can serve as a natural conversation opener. Recommendation: SmartValue Junior mandate with a long-term investment horizon (10+ years). The portfolio grows with the client — today's student becomes tomorrow's potential UHNW client.",herkunft:"Son of Fam. Lindenberg (VV00002) — starting university 2026, parents plan 100k starting capital",naechsterSchritt:"Raise student portfolio topic at Lindenberg cash consolidation meeting",quelleLabel:"NextGen (Client's Child)",herleitung:[{label:"Family Relation",value:"Son of Familie Lindenberg (VV00002)"},{label:"Age",value:"18 years — starting university 2026"},{label:"Parental Provision",value:"Planned: 100,000 € starting capital from exit proceeds"},{label:"Recommended Product",value:"SmartValue Junior mandate — early NextGen client engagement"}]},NM007:{beruf:"Former CEO Engineering Firm (sold)",kiDescription:"AI Analysis: Handelsblatt reported on 05.02.2026 on the sale of Müller Engineering to the Swedish Sandvik Group. The estimated net proceeds after taxes amount to approx. 6M €. Dipl.-Ing. Müller is based in the Rhein-Main catchment area (Darmstadt). An initial phone call on 10.02. showed general interest in the FairValue mandate. Risk: post-exit mandates are highly competitive — all major asset management firms will be making contact simultaneously. Use the time advantage: arrange a swift personal initial meeting in Frankfurt. Differentiation through owner-managed structure and personal client service.",herkunft:"Handelsblatt: Sale of engineering firm to Swedish group. Estimated net proceeds 6M €.",naechsterSchritt:"Schedule follow-up meeting after initial phone call",quelleLabel:"Press / Liquidity Event",herleitung:[{label:"Source",value:'Handelsblatt, 05.02.2026 — "Müller Engineering sold to Sandvik"'},{label:"Estimated Proceeds",value:"6,000,000 € net after taxes"},{label:"Region",value:"Rhein-Main (Darmstadt) — within catchment area"},{label:"First Contact",value:"Phone call on 10.02. — general interest in FairValue"},{label:"Competition",value:"High — after exit all asset management firms seek contact simultaneously"},{label:"Next Step",value:"Arrange personal initial meeting in Frankfurt"}]},NM008:{beruf:"Former CEO Fuchs Precision Engineering",kiDescription:"AI Analysis: Fresh press lead from Handelsblatt (06.03.2026): Dr. Martin Fuchs has sold Fuchs Präzisionstechnik to a Swedish group. The estimated proceeds are 4–6M € based on industry EBITDA multiples. The company is located in Frankfurt-Süd — right within the catchment area. No contact has been established yet, but Tim Keller (VV00001) could serve as a door-opener through the IHK Frankfurt network. Lead quality: medium — without a personal connection, the probability is 15%. Recommendation: deepen research, then pursue a warm introduction through the IHK network rather than cold outreach.",herkunft:"Handelsblatt: Dr. Martin Fuchs sells Fuchs Präzisionstechnik to a Swedish group. Estimated proceeds 4–6M €.",naechsterSchritt:"Deepen research, then personal outreach via IHK network",quelleLabel:"Press / Liquidity Event",herleitung:[{label:"Source",value:'Handelsblatt, 06.03.2026 — "Fuchs Präzisionstechnik goes to Sandvik"'},{label:"Estimated Proceeds",value:"4,000,000–6,000,000 € (EBITDA multiple estimated)"},{label:"Region",value:"Frankfurt-Süd — within catchment area"},{label:"Network",value:"IHK Frankfurt — potentially accessible through Tim Keller"},{label:"Status",value:"No contact yet — outreach via network planned"}]},NM009:{beruf:"Cultural Foundation",kiDescription:"AI Analysis: Stiftung Merian is a cultural foundation with approx. 4.2M € AuM, currently managed by DWS. Contact was established at the Stiftungstag 2025, where HRK LUNIS appeared as a sponsor. The foundation chairwoman Dr. Elisabeth Merian expressed dissatisfaction with DWS reporting and interest in an ESG-compliant foundation mandate. Foundation mandates are particularly valuable: long durations, regular inflows, and a multiplier effect within the foundation network. Recommendation: specialist foundation mandate with tailored ESG reporting and quarterly board presentations. Differentiation through personal service vs. DWS standard reporting.",herkunft:"Contact at Stiftungstag 2025 — cultural foundation, currently at DWS, interest in ESG foundation mandate",naechsterSchritt:"Send foundation mandate information package",quelleLabel:"Network Event",herleitung:[{label:"Event",value:"Stiftungstag 2025, Frankfurt — HRK LUNIS as sponsor"},{label:"Contact Person",value:"Dr. Elisabeth Merian, Foundation Board Chairwoman"},{label:"AuM at DWS",value:"approx. 4,200,000 € (stated in conversation)"},{label:"Interest",value:"ESG-compliant foundation mandate, dissatisfied with DWS reporting"},{label:"Next Step",value:"Send specialist foundation mandate information package"}]},NM010:{beruf:"Cardiologist, Practice Chain",kiDescription:"AI Analysis: Prof. König is a cardiologist and operator of a medical practice chain with an estimated total wealth of approx. 8M € (practice + real estate). Contact was established at the HRK LUNIS Unternehmer-Dinner on 02.03.2026 through Prof. Hartmann (VV00004) — a strong personal connection. The assets are currently spread across several banks without an asset management mandate — a typical fragmentation pattern among successful physicians. The initial meeting on 18.03.2026 is already scheduled. High lead value: 8M € potential at 45% probability. Recommendation: FairValue mandate consolidating all portfolios, complemented by PE Healthcare as a specialty investment theme.",herkunft:"Unternehmer-Dinner 02.03. — cardiologist with practice chain, estimated 8M €, meeting 18.03.",naechsterSchritt:"Initial meeting on 18.03.2026 — present FairValue mandate",quelleLabel:"Network Event",herleitung:[{label:"Event",value:"HRK LUNIS Unternehmer-Dinner, 02.03.2026"},{label:"Contact",value:"Introduced through Prof. Hartmann (VV00004)"},{label:"Estimated Assets",value:"approx. 8,000,000 € (practice chain + real estate)"},{label:"Current Situation",value:"Assets spread across several banks, no asset management mandate"},{label:"Meeting",value:"18.03.2026, 10:00 — initial meeting in Frankfurt"}]},NM011:{beruf:"Entrepreneur (Medical Technology)",kiDescription:"AI Analysis: Tax advisor Dr. Krause (network partner since 2020) proactively flagged this lead: Dr. Klaus Berger is preparing the sale of his medical technology GmbH. M&A advisors estimate proceeds at 5.5M €, with closing expected in Q3/2026. Multiplier leads through tax advisors have an above-average conversion rate, as the client already trusts his tax advisor's recommendation. Recommendation: three-way meeting (advisor + tax advisor + client) as a trust-building measure. Mind the timing: only become operationally active after closing, but start building the relationship now.",herkunft:"Tax advisor Dr. Krause recommends client ahead of planned company sale — estimated 5.5M €",naechsterSchritt:"Prepare outreach through tax advisor Dr. Krause",quelleLabel:"Multiplier (Tax Advisor)",herleitung:[{label:"Multiplier",value:"Tax advisor Dr. Krause (network partner since 2020)"},{label:"Context",value:"Sale of medical technology GmbH in preparation"},{label:"Estimated Proceeds",value:"5,500,000 € (valuation by M&A advisors)"},{label:"Timeline",value:"Closing expected Q3/2026"},{label:"Next Step",value:"Outreach through Dr. Krause — three-way meeting"}]},NM012:{kiDescription:"AI Analysis: Digital lead with a weak signal profile. Dr. Schulte visited the foundation management page 3 times (Feb/Mar 2026), opened the foundation newsletter with an above-average click rate, and registered for the Stiftungsforum on 25.04. The digital behavioural pattern indicates an active search for information on foundation management. Limitation: UHNW clients are generally not acquired via website — the probability is only 15%. Recommendation: approach personally at the Stiftungsforum, probe the volume and background. No active outbound before the event.",herkunft:"Website: 3× visits to /services/foundation-management + registration for Stiftungsforum — Name: Dr. Schulte",naechsterSchritt:"Contact personally after event registration",quelleLabel:"Digital Signal",herleitung:[{label:"Digital Signals",value:"3× page visits /services/foundation-management (Feb/Mar 2026)"},{label:"Newsletter",value:"Opened: Foundation Special (above-average click rate)"},{label:"Event Registration",value:"Stiftungsforum 25.04.2026 — name revealed upon registration: Dr. Schulte"},{label:"Assessment",value:"Weak lead — UHNW clients rarely come through website"},{label:"Next Step",value:"Contact personally after event registration"}]},NM013:{beruf:"Dentist (Practice Sale)",kiDescription:"AI Analysis: Successfully won mandate! Dr. Lisa Schreiber (dentist) signed the SmartValue mandate on 10.03.2026 following her practice sale in 2025 (net proceeds 1.8M €). Contact was established at the annual reception in 2025. Onboarding is underway, mandate starts 01.04.2026. This closed lead demonstrates: event-based acquisition among physicians following a practice sale works exceptionally well. Next steps: finalize onboarding, structure the initial investment. Medium-term: cross-selling (retirement planning, real estate). Long-term: multiplier potential within the Frankfurt physicians network.",herkunft:"Annual reception 2025 — dentist with practice sale. SmartValue mandate (1.8M) signed.",naechsterSchritt:"Complete onboarding — mandate starts 01.04.2026",quelleLabel:"Network Event",herleitung:[{label:"Event",value:"HRK LUNIS Annual Reception, December 2025"},{label:"Background",value:"Practice sale 2025, net proceeds 1,800,000 €"},{label:"Mandate",value:"SmartValue mandate — signed on 10.03.2026"},{label:"Next Step",value:"Complete onboarding, start 01.04.2026"}]},BM001:{beruf:"Existing Client",kiDescription:"AI Analysis: Urgent action required! Familie Lindenberg (VV00002) has had 5.5M € in cash sitting in a Commerzbank current account for 14 months — exit proceeds from the SaaS sale in 2024. The opportunity costs are considerable: approx. 275k €/year in foregone returns at a 5% target return, plus approx. 137k €/year in real purchasing power loss due to inflation. The client is broadly in agreement, the signature is still outstanding. Recommended strategy: 3-phase investment (2M immediately, 2M in Q3, 1.5M in Q4) to minimise risk through temporal diversification. Lead quality: very high (80%) — the client is convinced, only the formal conclusion is missing.",herkunft:"Fam. Lindenberg: 5.5M € cash for 14 months at Commerzbank. Opportunity cost approx. 275k €/year.",naechsterSchritt:"Finalise and sign 3-phase investment plan",quelleLabel:"Increased Liquidity",herleitung:[{label:"Data Source",value:"Consent query Commerzbank"},{label:"Cash Balance",value:"5,500,000 € in current account (exit proceeds 2024)"},{label:"Opportunity Cost",value:"approx. 275,000 €/year foregone at 5% target return"},{label:"Inflation Loss",value:"approx. 137,500 €/year at 2.5% inflation"},{label:"Recommended Strategy",value:"3-phase investment: 2M immediately, 2M Q3, 1.5M Q4"},{label:"Status",value:"Client broadly in agreement, signature outstanding"}]},BM002:{beruf:"Existing Client",kiDescription:"AI Analysis: Proactive lead from consent data query at Alte Leipziger. Tim Keller's life insurance policy (contract pre-2005) matures in Q3/Q4 2026 with a surrender value of 320k €. Tax-optimal: payout after 12 years is tax-free. Without advice the money would simply sit uninvested in the account. Recommendation: plan a proactive conversation BEFORE the maturity date — reinvest directly into the existing FairValue mandate. Return argument: 5–7% target return vs. 0% in a current account. The probability is 85% — the client already fully trusts HRK LUNIS.",herkunft:"Tim Keller: Alte Leipziger life insurance, surrender value 320k €, maturity Q3/2026. Reinvestment into mandate.",naechsterSchritt:"Prepare LV maturity Q3/2026 — reinvestment into FairValue mandate",quelleLabel:"Increased Liquidity",herleitung:[{label:"Data Source",value:"Consent query Alte Leipziger"},{label:"Insurer",value:"Alte Leipziger Lebensversicherung"},{label:"Surrender Value",value:"320,000 € (maturity Q3/Q4 2026)"},{label:"Tax Treatment",value:"Contract pre-2005: tax-free payout after 12 years"},{label:"Reinvestment Return",value:"Target return 5–7% p.a. vs. 0% on current account"},{label:"Next Step",value:"Mark maturity date in calendar, plan proactive conversation"}]},BM003:{beruf:"Existing Client",kiDescription:"AI Analysis: Consolidation potential with Tim Keller! Consent queries at UBS and Deutsche Bank reveal: 2.8M € in the UBS portfolio (balanced mandate, cost ratio 1.35%) plus 400k € cash at Deutsche Bank. By consolidating into the FairValue mandate (all-in fee 0.85%), the client saves approx. 16,000 €/year on 3.2M volume. Additionally, he benefits from unified reporting and holistic advisory instead of a fragmented wealth overview. The total mandate would rise to approx. 15.7M € — a significant revenue gain for HRK LUNIS. Recommendation: prepare a concrete comparison offer UBS vs. FairValue.",herkunft:"Tim Keller: 2.8M UBS portfolio + 400k DB cash. Consolidation saves approx. 16,000 €/year in costs.",naechsterSchritt:"Prepare comparison offer UBS vs. FairValue",quelleLabel:"Third-Party Bank Consolidation",herleitung:[{label:"Data Source",value:"Consent query UBS + Deutsche Bank"},{label:"UBS Portfolio Volume",value:"2,800,000 € (balanced mandate)"},{label:"DB Cash Balance",value:"400,000 € (fixed/call money deposit)"},{label:"UBS Cost Ratio",value:"1.35% p.a. (incl. transaction costs)"},{label:"HRK LUNIS FairValue",value:"0.85% p.a. (all-in fee)"},{label:"Annual Saving",value:"approx. 16,000 € on 3.2M volume"}]},BM004:{beruf:"Existing Client",kiDescription:"AI Analysis: Stiftung Weber (VV00003) holds 500k € in a fixed-term deposit at Sparkasse (2.0% until 2027). Upon maturity there is a consolidation opportunity into the specialist mandate: return of 4–5% vs. 2.0% = additional income of 10,000–15,000 €/year. For an educational foundation, these additional returns directly benefit grant-making activities — a strong argument. The timing is not yet acute (maturity 2027), but preparation should begin now. Recommendation: mark the maturity date in the calendar, initiate consolidation discussion with the foundation board from Q4/2026 onwards. Account for the foundation's safety-oriented investment approach.",herkunft:"Stiftung Weber: 500k fixed deposit at Sparkasse (2% until 2027). Transfer into specialist mandate at maturity.",naechsterSchritt:"Flag maturity 2027, consolidation meeting Q4/2026",quelleLabel:"Third-Party Bank Consolidation",herleitung:[{label:"Data Source",value:"Consent query Sparkasse"},{label:"Fixed Deposit Volume",value:"500,000 € (2.0% until 2027)"},{label:"Fixed Deposit Return",value:"2.0% p.a. = 10,000 €/year"},{label:"Return in Specialist Mandate",value:"4–5% p.a. = 20,000–25,000 €/year"},{label:"Additional Income p.a.",value:"approx. 10,000–15,000 € with comparable safety orientation"},{label:"Next Step",value:"Flag maturity 2027 — then consolidation meeting"}]},BM005:{beruf:"Existing Client",kiDescription:"AI Analysis: Prof. Hartmann (VV00004) holds 250k € at ING in a call money account (2.0% variable, trending downward). The FairValue mandate could realistically achieve 5–7% target return — additional income of 7,500–12,500 €/year. ING interest rates will continue to fall with the next ECB cuts, strengthening the argument for reallocation. Recommendation: raise the consolidation at the next regular PE appointment — low effort since Prof. Hartmann is already an existing client. No separate meeting required; the topic can be added as an agenda item.",herkunft:"Prof. Hartmann: 250k at ING (2.0% call money). Significantly higher return achievable in FairValue mandate.",naechsterSchritt:"Raise consolidation at next PE appointment",quelleLabel:"Third-Party Bank Consolidation",herleitung:[{label:"Data Source",value:"Consent query ING"},{label:"Call Money Volume",value:"250,000 € at ING (2.0% p.a., variable, declining)"},{label:"Call Money Return",value:"5,000 €/year"},{label:"Return in FairValue Mandate",value:"12,500–17,500 €/year (5–7% target return)"},{label:"Additional Income p.a.",value:"approx. 7,500–12,500 € at moderate risk"}]},BM006:{beruf:"Existing Client",kiDescription:"AI Analysis: Double opportunity with Familie Lindenberg! Currently in the SmartValue mandate (2.1M AuM). Once the 5.5M cash consolidation (BM001) is completed, AuM rises to 7.6M € — well above the FairValue threshold of 3M €. A mandate upgrade saves the client 15,200 €/year (1.05% SmartValue → 0.85% FairValue). Win-win: the client benefits from lower costs and more individualised service, HRK LUNIS significantly increases the managed volume. Recommendation: propose cash consolidation and mandate upgrade simultaneously — as a combined package the offer is more compelling.",herkunft:"Fam. Lindenberg: Currently 2.1M SmartValue. With cash (5.5M) AuM would be 7.6M → FairValue eligible. Cost saving: 15,200 €/yr.",naechsterSchritt:"Propose FairValue upgrade simultaneously with cash consolidation",quelleLabel:"Mandate Upgrade",herleitung:[{label:"Current Mandate",value:"SmartValue (AuM 2.1M, since 06/2024)"},{label:"Target AuM after Consolidation",value:"7,600,000 € (2.1M + 5.5M cash)"},{label:"FairValue Threshold",value:"3,000,000 € — overqualified after consolidation"},{label:"SmartValue Costs",value:"1.05% p.a."},{label:"FairValue Costs",value:"0.85% p.a. → saving 15,200 €/year"},{label:"Next Step",value:"Propose upgrade together with cash consolidation"}]},BM007:{beruf:"Existing Client",kiDescription:"AI Analysis: Maxim Meydarn (VV00005) is currently in the SmartValue mandate with 450k € AuM. He holds a Series A startup investment with an expected exit in 2–3 years. A successful exit could add 500k–1.5M €, potentially pushing AuM above the 3M FairValue threshold. The probability is moderate (40%), as startup exits are uncertain. Recommendation: no active pressure, but clarify the expected exit timeline at the next conversation. If the outlook is positive, the FairValue upgrade can be prepared. Long-term: Maxim Meydarn is 35 and has a growing tech-entrepreneur profile — a potential future UHNW client.",herkunft:"Maxim Meydarn: 450k SmartValue. Series A startup — FairValue upgrade possible upon exit (from 3M).",naechsterSchritt:"Clarify expected exit timeline in conversation",quelleLabel:"Mandate Upgrade",herleitung:[{label:"Current Mandate",value:"SmartValue (AuM 450,000 €, since 01/2025)"},{label:"Ongoing Startup",value:"Series A investment — expected exit in 2–3 years"},{label:"Estimated Exit Proceeds",value:"500,000–1,500,000 € (depending on valuation)"},{label:"FairValue Threshold",value:"From 3M AuM — reachable upon successful exit"}]},BM008:{beruf:"Existing Client",kiDescription:"AI Analysis: Strategically highly relevant lead! Tim Keller (62) is planning the succession of Keller Maschinenbau GmbH & Co. KG (3rd generation) over the next 3–5 years. The company value is estimated at 4.5M € (EBITDA multiple). Son Friedrich (28) is already working in the business and is the likely successor. A sale or transfer would bring substantial proceeds into private assets. Tax complexity: business asset exemptions and relief provisions need to be reviewed. Recommendation: coordinate succession advisory with tax and legal partners now — position HRK LUNIS as a holistic advisor. Cross-selling: also develop Friedrich as an independent client (see NM004).",herkunft:"Tim Keller (62 yrs): succession of Maschinenbau GmbH in 3–5 years. Estimated company value 4.5M €. Plan proceeds investment.",naechsterSchritt:"Coordinate succession advisory with tax and legal partners",quelleLabel:"Life Event",herleitung:[{label:"Trigger",value:"Age 62 + son Friedrich (28) in the business — succession in 3–5 years"},{label:"Company",value:"Keller Maschinenbau GmbH & Co. KG, 3rd generation"},{label:"Estimated Company Valuation",value:"4,500,000 € (EBITDA multiple)"},{label:"Tax Aspects",value:"Business asset exemption, relief provisions to review"},{label:"Next Step",value:"Coordinate succession advisory with tax and legal partners"}]},BM009:{beruf:"Existing Client",kiDescription:"AI Analysis: Prof. Hartmann (56) is planning retirement in 5–8 years. His cardiology private practice (established for 15+ years) has an estimated value of 800k € (tangible assets + goodwill). Possible successor: son Jan (resident physician, NM005) or an external buyer. The sale proceeds would increase the existing FairValue mandate. Long-term advisory approach: practice valuation, tax-optimised transfer, and investment of proceeds. Connection to NM005 (Jan Hartmann): in the case of internal succession, the intra-family wealth transfer becomes relevant.",herkunft:"Prof. Hartmann (56 yrs): practice sale planned in 5–8 years. Estimated valuation 800k. Proceeds into FairValue.",naechsterSchritt:"Discuss practice valuation and tax-optimised transfer",quelleLabel:"Life Event",herleitung:[{label:"Trigger",value:"Age 56, retirement planned in 5–8 years"},{label:"Practice",value:"Cardiology private practice, established for 15+ years"},{label:"Estimated Valuation",value:"800,000 € (tangible assets + goodwill)"},{label:"Possible Successor",value:"Son Jan (resident physician) or external buyer"}]},BM010:{beruf:"Existing Client",kiDescription:"AI Analysis: Elisabeth Keller (wife of Tim Keller) has been engaged in charitable work for over 10 years and is planning a family foundation. The planned foundation capital is 2M € from private assets. Strategic value for HRK LUNIS: foundations bind clients and assets over the long term — a virtually non-cancellable mandate. Tax advantage: special expense deduction of up to 1M € in the year of establishment. The foundation also serves as a succession instrument for the family (total assets >20M). Recommendation: discuss the foundation concept with Elisabeth and position it as a comprehensive family governance instrument.",herkunft:"Elisabeth Keller: 10+ years of charitable work. Explore family foundation as succession instrument, capital 2M €.",naechsterSchritt:"Discuss foundation concept with Elisabeth Keller",quelleLabel:"Foundation Establishment",herleitung:[{label:"Trigger",value:"Total assets >20M, age >60 — foundation as succession instrument"},{label:"Initiator",value:"Elisabeth Keller, foundation board (voluntary)"},{label:"Planned Foundation Capital",value:"2,000,000 € from private assets"},{label:"Tax Advantages",value:"Special expense deduction up to 1M € in year of establishment"},{label:"Long-Term Value",value:"Foundation binds client + assets to HRK LUNIS long-term"}]},BM011:{beruf:"Existing Client",kiDescription:"AI Analysis: Attention — 91 days without contact with Familie Lindenberg! For top clients, a contact pause of >90 days is a warning signal for client retention. The Unternehmer-Dinner on 25.03.2026 provides the perfect conversation opener: Fam. Lindenberg (SaaS exit entrepreneurs) are an ideal match for the target audience. Important: position the invitation as genuine added value, not as a sales pitch. Strategy: send the invitation personally, then naturally transition to cash consolidation (BM001) and mandate upgrade (BM006) during conversation. Activation urgently recommended.",herkunft:"Fam. Lindenberg: Profile matches Unternehmer-Dinner on 25.03. Invitation as opportunity — 91 days without contact!",naechsterSchritt:"Send invitation to Unternehmer-Dinner on 25.03.",quelleLabel:"Event Invitation (Activation)",herleitung:[{label:"Event",value:"Unternehmer-Dinner on 25.03.2026"},{label:"Client Profile",value:"SaaS exit entrepreneur — perfect match for target audience"},{label:"Last Contact",value:"91 days — activation urgently recommended"},{label:"Strategy",value:'Event invitation as conversation opener — not a "sales call"'}]},BM012:{beruf:"Existing Client",kiDescription:"AI Analysis: URGENT — Performance warning! Stiftung Weber has lost -8.2% since its peak and is approaching the -10% loss threshold. Upon reaching the -10% mark, a regulatory loss threshold notification is automatically triggered — this must absolutely be communicated proactively BEFORE the client notices it themselves. Cause: bond segment under pressure from rising interest rates. Recommended action: call immediately, explain the situation, propose rebalancing (shorten bond duration). Proactive communication strengthens trust — reactive action after a threshold notification appears defensive.",herkunft:"Stiftung Weber: -8.2% performance, near 10% loss threshold. Proactive conversation urgently recommended.",naechsterSchritt:"Conduct proactive conversation with foundation board — propose rebalancing",quelleLabel:"Performance Adjustment",herleitung:[{label:"Current Performance",value:"-8.2% since peak (loss threshold: -10%)"},{label:"Cause",value:"Bond segment under pressure from rising interest rates"},{label:"Risk",value:"Upon reaching -10% → loss threshold notification to client"},{label:"Recommendation",value:"Call proactively BEFORE client notices themselves"},{label:"Action",value:"Propose rebalancing: shorten bond duration"}]},BM013:{beruf:"Existing Client",kiDescription:"AI Analysis: Turn a compliance obligation into a sales opportunity! Maxim Meydarn's WpHG questionnaire is 14 days overdue — a regulatory requirement. Use the mandatory appointment wisely: simultaneously discuss crypto reporting (Maxim is a tech entrepreneur with a crypto affinity), address angel portfolio expansion and ESG impact investments. Update the risk appetite during the WpHG questionnaire — potentially unlock new asset classes. What starts as a regulatory obligation becomes a valuable advisory conversation with cross-selling potential.",herkunft:"Maxim Meydarn: WpHG questionnaire 14 days overdue. Use compliance appointment to discuss crypto reporting.",naechsterSchritt:"Update WpHG questionnaire + discuss crypto reporting simultaneously",quelleLabel:"Compliance Contact Opportunity",herleitung:[{label:"Compliance Obligation",value:"WpHG questionnaire 14 days overdue — regulatory requirement"},{label:"Cross-Selling",value:"Use appointment for: crypto reporting, angel portfolio, ESG impact"},{label:"Mandate Upgrade",value:"Review risk appetite — potentially unlock new asset classes"},{label:"Next Step",value:"Appointment on 12.03. — combine WpHG + advisory conversation"}]},BM014:{beruf:"Existing Client",kiDescription:"AI Analysis: Prof. Hartmann (Head of Cardiology) currently has only 200k € in PE Healthcare — that is 2.9% of his AuM, significantly below the target corridor of 7–10%. As a cardiologist, he has unique industry knowledge that makes his PE investments in healthcare particularly well-informed. PE Healthcare Fund II offers an ideal opportunity to increase the allocation to 500k € (+300k). Expected IRR: 12–15% p.a. based on historical healthcare PE returns. Recommendation: prepare subscription documents and propose the PE expansion at the next appointment. Probability is 75% — the client knows and values the asset class.",herkunft:"Prof. Hartmann: Increase PE Healthcare allocation from 200k to 500k. Cardiology expertise = information advantage.",naechsterSchritt:"Prepare PE Healthcare Fund II subscription documents",quelleLabel:"Mandate Expansion",herleitung:[{label:"Current PE Allocation",value:"200,000 € (PE Healthcare Fund, since 01/2022)"},{label:"Share of AuM",value:"2.9% — significantly below target 7–10%"},{label:"Professional Expertise",value:"Head of Cardiology — unique industry knowledge"},{label:"Target PE Allocation",value:"500,000 € (+300k in PE Healthcare Fund II)"},{label:"Expected Return",value:"IRR 12–15% p.a. (healthcare PE historically)"}]},BM015:{beruf:"Existing Client",kiDescription:"AI Analysis: Stiftung Weber currently has an ESG score of 72 (Art. 8 specialist mandate), with a target of >80 (Art. 9 compliance). An upgrade to Art. 9 would reinforce the foundation's educational mission and simultaneously bring regulatory advantages: easier access to grant funding and a stronger positioning when approaching donors. No direct revenue impact, but a high retention effect and differentiation from competitors. Recommendation: prepare an Art. 9 mandate proposal for the next foundation board meeting — the board decides, not the individual contact.",herkunft:"Stiftung Weber: ESG score 72, target >80. Upgrade Art.8 to Art.9 — reinforces foundation's educational mission.",naechsterSchritt:"Prepare Art.9 mandate proposal for next foundation board meeting",quelleLabel:"Mandate Expansion",herleitung:[{label:"Current ESG Score",value:"72 out of 100 (Art. 8 specialist mandate)"},{label:"Target ESG Score",value:">80 (Art. 9 compliance)"},{label:"Foundation Purpose",value:"Educational promotion — Art. 9 reinforces the mission"},{label:"Regulatory Advantage",value:"Art. 9 facilitates grant access + donor outreach"}]},BM016:{beruf:"Existing Client",kiDescription:'AI Analysis: Our internal signal analysis has identified a strong cluster of interest in defense/defense-sector investments at Tim Keller. Four independent data points confirm the pattern: (1) Our whitepaper "Defense & Aerospace — Investment Opportunities in the New Geopolitical Environment" was read in full (14 minutes dwell time). (2) On LinkedIn, Tim Keller has actively participated in discussions on European defense policy and defense ETFs — with multiple comments and shares. (3) Our thematic newsletter "Defense Sector: Portfolio Allocation 2026" was opened and all links clicked. (4) Approximately 2 months ago he attended our event "Geopolitics & Portfolio Strategy". Recommendation: proactively schedule a meeting and present the defense investment thesis. Starting point: our new whitepaper "European Defense Stocks — Due Diligence Report 2026" (published 2 days ago). Potential allocation: 500k–1.5M € from the existing FairValue mandate (12.5M AuM) — corresponding to 4–12% of the portfolio, in line with his risk profile.',herkunft:"Tim Keller: Internal analysis shows strong interest in defense investments — whitepaper read, LinkedIn discussions, newsletter opened, event attended.",naechsterSchritt:"Schedule meeting — discuss defense investment thesis and whitepaper",quelleLabel:"Digital Signal / Internal Analysis",herleitung:[{label:"Whitepaper",value:"Defense & Aerospace whitepaper read in full (14 min. dwell time)"},{label:"LinkedIn Activity",value:"Active discussion contributions on European defense policy and defense ETFs"},{label:"Newsletter",value:"Defense sector newsletter opened — all links clicked (click rate 100%)"},{label:"Event Attendance",value:'Event "Geopolitics & Portfolio Strategy" attended (January 2026)'},{label:"New Whitepaper",value:'"European Defense Stocks — Due Diligence Report 2026" (published 2 days ago)'},{label:"Potential Allocation",value:"500k–1.5M € (4–12% of the 12.5M FairValue mandate)"}]}};export{s as L,o as P};
